components.draw:
const pos = state.scores.filter((s) => s[1] === 1).map((s) => s[0]), neg = state.scores.filter((s) => s[1] === 0).map((s) => s[0]);
return [
  kde(neg, { range: [0, 1], fill: true, color: 'blue' }), kde(neg, { range: [0, 1], color: 'blue' }),
  kde(pos, { range: [0, 1], fill: true, color: 'green' }), kde(pos, { range: [0, 1], color: 'green' }),
  vline(state.t, { color: 'gray', dashed: true })
];

components.value:
const tp = state.scores.filter((s) => s[0] >= state.t && s[1] === 1).length;
const fp = state.scores.filter((s) => s[0] >= state.t && s[1] === 0).length;
const fn = state.scores.filter((s) => s[0] < state.t && s[1] === 1).length;
return 2 * tp / ((2 * tp + fp + fn) || 1);
